Here is a Python implementation of the Template Method pattern for sorting:

```python
from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def __init__(self, data):
        self.data = list(data)

    def sort(self):
        """Template method - skeleton of the algorithm"""
        self._sort_impl()
        return self.data

    @abstractmethod
    def _sort_impl(self):
        """Primitive operation to be implemented by subclasses"""
        pass

    def compare(self, a, b):
        return a > b

    def swap(self, i, j):
        self.data[i], self.data[j] = self.data[j], self.data[i]


class BubbleSort(SortAlgorithm):
    def _sort_impl(self):
        n = len(self.data)
        for i in range(n):
            for j in range(0, n - i - 1):
                if self.compare(self.data[j], self.data[j + 1]):
                    self.swap(j, j + 1)


class SelectionSort(SortAlgorithm):
    def _sort_impl(self):
        n = len(self.data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(self.data[min_idx], self.data[j]):
                    min_idx = j
            if min_idx != i:
                self.swap(i, min_idx)


# Test
if __name__ == "__main__":
    ints = [64, 25, 12, 22, 11]
    strs = ["banana", "apple", "cherry", "date"]

    for Algo in [BubbleSort, SelectionSort]:
        bs = Algo(ints)
        print(f"{Algo.__name__} ints: ", bs.sort())

        ss = Algo(strs)
        print(f"{Algo.__name__} strs: ", ss.sort())
```

`SortAlgorithm` defines the template `sort()` and the primitive operations `compare` and `swap`. `BubbleSort` and `SelectionSort` provide their own `_sort_impl` algorithm while reusing the same `compare`/`swap` primitives.

